            </div>



        </div>

     

      <div class = "row mt-3" v-if="selection_type">
                <div class="col-md-3" v-if="selection_type === 'Item'">
                  <label class="form-label">Item</label>
                  <multiselect 
                    v-model="gate_pass_item"
