                  ></multiselect>
                </div>
                <div class="col-md-3" v-if="selection_type === 'Asset'">
            <label class="form-label small">Select An Asset</label>
            <multiselect 
                v-model="gate_pass_asset"
                :options= "assets"
                placeholder="Select An Asset"
                label="name"
