                v-model="item_description"
            />
        </div>

                 <div class="col-md-3"  v-if="selection_type === 'Item'">
                    <label class="form-label small">Unit</label>
                    <multiselect 
                        v-model="unit"
                        :options="units"
                        placeholder="select unit"
                        label="short_name"
                        :searchable="true"        
                        :multiple="false"
                        :required="true"
                      
                    ></multiselect>
                </div> 
                <div class="col-md-3"  v-if="selection_type === 'Item'">
                  <label class="form-label">Quantity</label>
                  <input type="number" class="form-control" placeholder="Enter Quantity" v-model="quantity"  step="any">
                </div>
                <div class="col-md-12 col-lg-12 mb-2 text-end">
            <button 
                type="button" 
                class="btn btn-outline-success btn-sm mt-4"
                @click="pushGatePassItem()"
            >
                <i class="bi bi-plus-square"/>
                Add Item
            </button>
        </div>
        <div 
        v-if="gatePassItems.length>0"
        class="row mb-3">
        <div class="col-12">
          <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
            <div class="custom-table table3">
                <v-client-table 
                    :data="gatePassItems" 
                    :columns="gatePassItemColumns" 
                    :options="table_option"
                >
                    <template #actions="props">
                        <a href="javascript:void(0);" title="Delete" @click="pullGatePassItem(props.row.Sno)">
                            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" fill="currentColor" class="bi bi-trash text-danger" viewBox="0 0 16 16">
                                <path d="M5.5 5.5A.5.5 0 0 1 6 6v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m2.5 0a.5.5 0 0 1 .5.5v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m3 .5a.5.5 0 0 0-1 0v6a.5.5 0 0 0 1 0z"/>
                                <path d="M14.5 3a1 1 0 0 1-1 1H13v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V4h-.5a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1H6a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1h3.5a1 1 0 0 1 1 1z"/>
                            </svg>
                        </a>
                    </template>
                </v-client-table>
            </div>
            </div>
            </div>
        </div>
    </div>
              </div>

                                    <!-- Open Jobcard Card -->
<div 
    v-if="selectedAssetOpenJobcards.length > 0"
    class="col-6 mb-2 my-2"
>
    <div class="card border-warning shadow-sm">
        <div class="card-body py-2">
            <h6 class="text-warning mb-1 text-center">
                Asset has Open Jobcards
            </h6>
            <div class="d-flex flex-wrap gap-2">
                <span 
                    v-for="jc in selectedAssetOpenJobcards" 
                    :key="jc"
                    class="badge bg-warning text-dark"
                >
                    Jobcard No. {{ jc }}
                </span>
            </div>
        </div>
    </div>
</div>

        <div class="text-center gap-2 justify-content-end">
            <button type="button" class="btn btn-danger me-3" @click="gate_pass = false; resetForm();">Cancel</button>
            <button type="submit" class="btn btn-primary" :disabled="loading  ||  asset?.has_open_jobcard === true ">
                <span v-if="loading" class="spinner-border spinner-border-sm me-1" role="status" aria-hidden="true"></span>
                <span v-else>Register</span>
            </button>
        </div>
    </form>
             <!-- gate pass registration form ends-->

        <!-- loading spinner starts -->
        <div v-if="loading_spinner" v-html="tableShimmer()"></div>
        <!-- Loading spinner ends -->

        <div v-else class="row layout-top-spacing">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
                        <v-client-table :data="gatePass" :columns="columns" :options="table_option">
                            <template #actions="props">
                                <a v-if="props.row.status.id == 3" href="javascript:;" class="me-2" @click="printGatePass(props.row)">
                                    <i class="bi bi-printer fs-5 text-success"/>
                                </a>

                                <a href="javascript:;" @click="viewGatePass(props.row)" data-bs-toggle="modal" data-bs-target="#gate-pass-modal">
                                    <i class="bi bi-eye fs-5 text-primary"/>
                                </a>

                                            <a
                  href="javascript:void(0);"
                  class="text-secondary position-relative me-2"
                  @click="
                  viewGatePass(props.row)
                    noteModalRef.open(null, props.row.id);
                  "
                >
                  <i class="bi bi-journal-bookmark-fill fs-5"></i>
                  <span
                    v-if="props.row.logs_count > 0"
                    class="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger"
                    style="font-size: 9px; min-width: 16px; padding: 2px 4px"
                  >
                    {{ props.row.logs_count }}
                  </span>
                </a>

                                
                            </template>

                            <template #status="props">
                                            <span class="badge inv-status" :class="'badge-' + props.row.status.color">
                                               {{ props.row.status.name }}
                                             </span>
                            </template>

                        </v-client-table>
                    </div>
                </div>
            </div>
        </div>

        <!-- View Gate Pass Items Modal -->
        <div class="modal fade mymodal" id="gate-pass-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="gatePassModalLabel" aria-hidden="true">
            <div class="modal-dialog modal-xl">
                <div class="modal-content">
                    <div class="modal-header">
                        <h1 class="modal-title fs-5" id="gatePassModalLabel">
                            Gate Pass Items - #{{ selectedGatePass?.id|| 'N/A' }}
                        </h1>
                        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" id="close-preview-modal" ></button>
                    </div>
                    <div class="modal-body">
                        <!-- Gate Pass Details -->
<table class="table table-bordered" v-if="selectedGatePass">
    <tbody>
        <tr>
            <th>Gate Pass ID</th>
            <td>{{ selectedGatePass.id }}</td>
            <th>Asset</th>
            <td>{{ selectedGatePass.asset }}</td>
        </tr>
        <tr>
            <th>Source</th>
            <td>{{ selectedGatePass.source }}</td>
            <th>Destination</th>
            <td>{{ selectedGatePass.destination }}</td>

        </tr>
        <tr>
            <th>Security</th>
            <td>{{ selectedGatePass.security_name }}</td>
            <th>Driver</th>
            <td>{{ selectedGatePass.driver_name }}</td>
        </tr>

        <tr>
            <th>Issue Note #</th>
            <td>{{ selectedGatePass.good_issue_note_id ?? 'N/A' }}</td>
            <th>Status</th>
            <td>
                 <span class="badge inv-status" :class="'badge-' + selectedGatePass.status.color">
                    {{ selectedGatePass.status.name }}
                 </span>
            </td>
        </tr>

        <tr>
            <th>Description</th>
            <td colspan="3">{{ selectedGatePass.description }}</td>
        </tr>
    </tbody>
</table>

                        <!-- Items Table -->
                         <div class="panel mt-2">
                        <div class="custom-table table3">
                            <v-client-table 
                                :data="items" 
                                :columns="Itemscolumn" 
                                :options="table_option"
                                v-if="items.length > 0"
                            >
                            </v-client-table>
                            <div v-else class="text-center p-4">
                                <p class="text-muted">No items found for this gate pass</p>
                            </div>
                        </div>
                        </div>
<div v-if="user_permissions.includes('can_approve_gate_pass')">
                        <h4>Approval Actions</h4>
                        <div  class="text-center">
<h4>Approval Actions</h4>
<div class="text-center">
<form  @submit.prevent>
    <ApprovalComponent
        v-model:modelValue="status"
        v-model:remarkValue="remark"
        :spinner="spinner"
        :loadingSpinner="loadingSpinner"
        @submit="approveGatePass"
    />
</form>
</div>
                        </div>
                      
</div>

                    </div>
                    <div class="modal-footer">
                         <button v-if="selectedGatePass?.status_id == 3" type="button" class="btn btn-success me-2" @click="printGatePass(selectedGatePass)"><i class="bi bi-printer fs-5"/></button>
                        <button type="button" class="btn btn-secondary" data-bs-dismiss="modal" >Close</button>
                    </div>
                </div>
            </div>
        </div>
    </div>


        <NoteModal
      ref="noteModalRef"
      :source-id="grn_id"
      source="GATE_PASS"
      module="GATE PASS"
      title="Gate Pass"
      @logs-updated="(count) => (selectedGatePass.logs_count = count)"
    />

</template>



<script setup>
    import { onMounted, ref, inject, watch,computed } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    import NoteModal from "@/components/reusables/NoteModal.vue";
    useMeta({ title: 'Gate Passes' });  
    import ApprovalComponent from '@/components/reusables/ApprovalComponent.vue';
    const showMessage = inject('showMessage');
    const showError = inject('showError');
    const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
    const formatDate = inject('formatDate');
    const tableShimmer = inject('tableShimmer');
    const loadingSpinner = inject('loadingSpinner'); 
    const date = ref(new Date().toISOString().split('T')[0]);
    const gate_pass = ref(false);
    const asset = ref(null);
    const gate_pass_asset = ref(null);
    const driver_name = ref('');
    const security_name = ref('');
    const description = ref('');
    const item_description = ref('');
    const loading = ref(false);
    const selection_type = ref();
    const noteModalRef = ref(null);
    const cargo = ref({
                           id : 0,
                           name : 'NO'
                        })
    const gate_pass_item = ref(null);
    const issueNote = ref('')
    
    const loading_spinner = ref(false);
    const columns = ref(['SNo','gatePass','issuer','asset','odometer','destination','driver','security','date','status', 'actions']);
    const Itemscolumn = ref(['SNo','item','category','unit','quantity']);    
    const gatePass = ref([]);
    const selectedGatePass = ref(null);
    
    const table_option = ref({
        perPage: 20,
        perPageValues: [20, 50 ,100],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['SNo', 'name','short_name','status'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });


    const gatePassItems = ref([]);
    const gatePassItemColumns = ref(['Sno', 'item','description', 'unit', 'quantity', 'actions']);
    const item = ref('');
    const unit = ref(null);
    const quantity = ref('');
    const units = ref([]);

    const getUnits = async () => {
        try {
            const response = await axiosInstance.get('units');
            units.value = response.data;
        } catch (error) {
            console.error('Error fetching units:', error);
            showError('Failed to load units');
        }
    };

    const items = ref([]);
    const pushGatePassItem = () => {
        if (!gate_pass_item.value && !gate_pass_asset.value) {
            showError('Please provide either an item name or select an asset');
            return;
        }
        gatePassItems.value.push({
            Sno: gatePassItems.value.length + 1,
            item_id: gate_pass_item.value?.id || null,
            description: selection_type.value === 'Asset' ? 'ASSET CARRIED' : item_description.value,
            item: gate_pass_item.value?.name || gate_pass_asset.value?.name,
            asset_id: gate_pass_asset.value?.id || null,
            asset: gate_pass_asset.value?.name + ' - ' + gate_pass_asset.value?.type_name,
            unit_id: unit.value?.id,
            unit: unit.value?.short_name,
            quantity: selection_type.value === 'Asset' ? 1 : quantity.value,
        });

        gate_pass_item.value = null;
        unit.value = null;
        gate_pass_asset.value = null;
        quantity.value = '';
        item_description.value = '';
    };

    const pullGatePassItem = (sno) => {
        gatePassItems.value = gatePassItems.value.filter(item => item.Sno !== sno);
        gatePassItems.value = gatePassItems.value.map((item, index) => ({
            ...item,
            Sno: index + 1
        }));
    };


    const getGatePasses = async () => {
        loading_spinner.value = true;
        try {
            const response = await axiosInstance.get(`/gate-passes?date=${date.value}`);
            gatePass.value = response.data.map((item, index) => {
                // const items = item.good_issue_note?.items || item.items;
                return {
                    ...item,
                    SNo: index + 1,
                    odometer : item.current_reading,
                    gatePass: item.id,
                    GIN: item.good_issue_note_id || '--',
                    current_reading: item.current_reading,
                    return_reading: item.return_reading,
                    driver: item.driver_name,
                    security: item.security_name,
                    description: item.remark,
                    date: item.date,
                    asset: item.asset?.name + ' - ' + item.asset?.type_name,
                    assetNo: item.asset?.name,
                    assetType: item.asset?.type_name,
                    source: item.source_store?.name && item.source_store?.project?.short_name 
                        ? item.source_store.name + ' - ' + item.source_store.project.short_name 
                        : item.source_location,
                    destination: item.destination_store?.name && item.destination_store?.project?.short_name 
                        ? item.destination_store.name + ' - ' + item.destination_store.project.short_name 
                        : item.destination_location,
                    // items: items,
                    issuer: item.good_issue_note?.issuer?.name || item.issuer?.name,
                };
            });
        } catch (error) {
            console.log(error);
            showError(error.message);
        } finally {
            loading_spinner.value = false;
        }
    };

  const viewGatePass = (row) => {
    selectedGatePass.value = row;
    
    // ✅ Check good_issue_note.items first, then fall back to row.items
    const sourceItems = (row.good_issue_note?.items?.length > 0)
        ? row.good_issue_note.items
        : row.items;

    if (sourceItems && sourceItems.length > 0) {
        items.value = sourceItems.map((item, index) => ({
            SNo: index + 1,
            item: item.item?.name || item.store_item?.item?.name || item?.asset?.name + ' - ' + item?.asset?.type_name,
            category: item.store_item?.item?.category?.name || item.item?.category?.name || '--',
            unit: item.store_item?.item?.unit?.short_name || item.unit?.short_name || '--',
            quantity: item.quantity || '0'
        }));
    } else {
        items.value = [];
    }
};



    const printGatePass = async (row) => {
        try {
            const iframe = document.createElement("iframe");
            iframe.style.display = "none";
            document.body.appendChild(iframe);
            const printItems = (row.good_issue_note?.items?.length > 0)
    ? row.good_issue_note.items
    : row.items || [];
const hasItems = printItems.length > 0;

const printContent = `
<!DOCTYPE html>
<html>
<head>
<title>Print Gate Pass</title>
<style>
  body { font-family: 'Segoe UI', Arial, sans-serif; margin: 40px; font-size: 13px; color: #222; }
  .header { display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid #000; padding-bottom: 10px; }
  .logo { width: 150px; height: auto; }
  .gatepass-box { border: 2px solid #000; padding: 6px 14px; font-weight: bold; font-size: 14px; border-radius: 6px; background: #f9f9f9; box-shadow: 0 0 3px rgba(0,0,0,0.2); }
  .company-title { text-align: center; margin: 25px 0 15px 0; }
  .company-title h2 { margin: 0; font-size: 18px; text-transform: uppercase;  }
  .details { margin-top: 15px; line-height: 2; }
  .line-field { display: flex; justify-content: space-between; margin-bottom: 6px; }
  .label { width: 35%; font-weight: bold; }
  .value { flex: 1; border-bottom: 1px solid #000; text-align: center; padding-bottom: 2px; }
  table { width: 100%; border-collapse: collapse; margin-top: 15px; border-radius: 6px; overflow: hidden; }
  table.items thead th { background: #f0f0f0; border: 1px solid #000; font-weight: bold; text-align: center; }
  table.items td { border: 1px solid #000; padding: 6px; vertical-align: middle; text-align: center; }
  .signatures { margin-top: 40px; display: flex; justify-content: space-between; align-items: center; }
  .signature-box { text-align: center; width: 45%; }
  .signature-line { margin-top: 50px; border-top: 1px solid #000; width: 80%; margin-left: auto; margin-right: auto; }

  @media print { body { margin: 10mm; } .no-print { display: none; } }
</style>
</head>
<body>

<div class="header">
  <img src="https://bushman.ink/copex.jpg" class="logo" />
  <div class="gatepass-box">
    PASS NO: <span style="color:red;">${"00" + row.id || ''}</span><br>
    GIN NO: ${row.good_issue_note_id}<br>
    Date : ${formatDate(row.date)}
  </div>
</div>

<div class="company-title">
  <h2>Gate Pass for Construction Equipment / Vehicles</h2>
</div>

<table style="width:100%; border-collapse:separate; border-spacing:0 8px; margin-top:15px; font-size:13px;">
  <tr>
    <td style="font-weight:bold; width:20%;">Driver Name:</td>
    <td style="border-bottom:1px solid #000; padding:4px;">${row.driver_name || ''}</td>
     <td style="font-weight:bold; padding-left:20px;">Security Name:</td>
    <td style="border-bottom:1px solid #000; padding:4px;">${row.security_name || ''}</td>
  </tr>
  <tr>
    <td style="font-weight:bold;">Reg No:</td>
    <td style="border-bottom:1px solid #000; padding:4px;">${row.assetNo || ''}</td>
    <td style="font-weight:bold; padding-left:20px;">Type:</td>
    <td style="border-bottom:1px solid #000; padding:4px;">${row.assetType || ''}</td>
  </tr>
  <tr>
    <td style="font-weight:bold;">Start Kms/Hrs:</td>
    <td style="border-bottom:1px solid #000; padding:4px;">${row.current_reading || '--'}</td>
    <td style="font-weight:bold; padding-left:20px;">Return&nbsp;Kms/Hrs:</td>
    <td style="border-bottom:1px solid #000; padding:4px; white-space:nowrap;">${row.return_reading || '--'}</td>
  </tr>
  <tr>
    <td style="font-weight:bold;">Source Location:</td>
    <td style="border-bottom:1px solid #000; padding:4px;">${row.source || ''}</td>
    <td style="font-weight:bold; padding-left:20px;">Destination:</td>
    <td style="border-bottom:1px solid #000; padding:4px;">${row.destination || ''}</td>
  </tr>
</table>

${row.description ? `
<div style="margin-top:15px;">
  <p style="margin:0;"><span style="font-weight:bold;">Description:</span> ${row.description || ''}</p>
</div>
`: ``}

<div style="margin-top:15px;">
  <p style="margin:0;"><span style="font-weight:bold;">ITEMS CARRIED ? : </span> ${row.has_cargo ? 'YES' : 'NO'}</p>
</div>

<table style="width:100%; border-collapse:separate; border-spacing:0 8px; margin-top:15px; font-size:13px;">
  </tr>

</table>

${hasItems ? `
<h4 style="margin-top:25px;">CARRIED ITEMS:</h4>
<table class="items">
  <thead>
    <tr>
      <th>SN</th>
      <th>Item</th>
      <th>Description</th>
      <th>Quantity</th>
    </tr>
  </thead>
  <tbody>
    ${printItems.map((item, index) => `
    <tr>
      <td>${index + 1}</td>
      <td>${item.store_item?.item?.name || item.item?.name || item?.asset?.name + ' - ' + item?.asset?.type_name}</td>
      <td>${item.description || '--'}</td>
      <td style="text-align: right;">${item.quantity || '0'}</td>
    </tr>`).join("")}
  </tbody>
</table>
` : ''}

<div class="signatures">
<div class="signature-box">
    <div class="signature-line"></div>
    <p>Issuer's Sign ( ${row.issuer} )</p>
  </div>
  <div class="signature-box">
    <div class="signature-line"></div>
    <p>Driver's Sign</p>
  </div>
  <div class="signature-box">
    <div class="signature-line"></div>
    <p>Workshop's Sign</p>
  </div>
   <div class="signature-box">
    <div class="signature-line"></div>
    <p>Security Sign</p>
  </div>
</div>

</body>
</html>
`;

            const iframeDoc = iframe.contentWindow.document;
            iframeDoc.open();
            iframeDoc.write(printContent);
            iframeDoc.close();

            iframe.onload = () => {
                iframe.contentWindow.focus();
                iframe.contentWindow.print();
                setTimeout(() => {
                    document.body.removeChild(iframe);
                }, 1000);
            };
        } catch (error) {
            console.error('Print error:', error);
            showError(`Failed to print gate pass: ${error.message}`);
        }
    };

const assets= ref([])
const getAssets = async ()=>{
  const response = await axiosInstance.get('requisition-assets')
  assets.value = response.data.assets.map((item)=>({
  ...item,
  name : item.asset_name + ' - ' + item.asset_type,
  id: item.asset_id
  }))
}

const selectedAssetOpenJobcards = computed(() => {
    if (!asset.value) return []
    if (asset.value.has_open_jobcard) {
        return asset.value.jobcard_details
    }
    return []
})

const item_lists = ref([])
const getItems = async () =>{
  const response = await axiosInstance.get('item-list')
  item_lists.value = response.data.map((item)=>({
  ...item,
  name : item.name + ' - ' + item.description
  }))
}


const pass_date = ref('');
const source_location = ref('')
const destination_location = ref('')
const current_reading = ref('')
const sendNotification = inject('sendGroupNotification')
const registerGatePass = async () => {
  loading.value = true;
  const payload = {
    issuer_id: JSON.parse(localStorage.getItem("user")).id,
    asset_id: asset.value.id,
    driver_name: driver_name.value,
    source_location: source_location.value,
    destination_location: destination_location.value,
    security_name: security_name.value,
    remark: description.value,
    date : pass_date.value,
    items:gatePassItems.value,
    current_reading : current_reading.value,
    good_issue_note_id :issueNote.value.good_issue_note_id,
    has_cargo : cargo.value.id
  };

  const message = 'Gate Pass with ' + cargo.value.name + ' cargo was created by ' + JSON.parse(localStorage.getItem("user")).name + ",\n\n" + description.value 

  try {   
    const response = await axiosInstance.post('gate-passes', payload);
    sendNotification('GatePass Creation !',message ,'GATE_PASS')
    showMessage('Gate Pass created successfully!');
    getGatePasses()
    resetForm()
    gate_pass.value = false;
  } catch (error) {
    console.log(error)
    showError(error.message);
  }finally{
    loading.value = false;
  }
};

const resetForm = () => {
    asset.value = null;
    gate_pass_asset.value = null;
    driver_name.value = '';
    security_name.value = '';
    description.value = '';
    item_description.value = '';
    selection_type.value = null;
    gate_pass_item.value = null;
    unit.value = null;
    quantity.value = '';
    gatePassItems.value = [];
    source_location.value = null;
    destination_location.value = null;
    pass_date.value = '';    
};

const issueNotes = ref([])
const getIssueNotes = async()=>{
  const response = await axiosInstance.get('requisitions?approval_group_id=6&status_id=15')
  issueNotes.value = response.data.map((item)=>({
    ...item,
    name : item.description  +  ' '+ item.project +' '+ item.date,
     good_issue_note_id: item.issueNote?.[0]?.id ?? null,
  }))
}

watch(date, () => {
    getGatePasses();
});

watch(selection_type, () => {
    gatePassItems.value = []
    description.value = ''
    if(selection_type.value ==='From Issue Note'){
        getIssueNotes()
    }
});

watch(issueNote, () => {
description.value = issueNote.value.name
  gatePassItems.value = issueNote.value.items.map((item,index)=>({
    ...item,
    Sno : index + 1,
    item :item.remark
  }))
});

watch(asset, (newAsset) => {
    if (newAsset && newAsset.current_reading) {
        // Auto-fill with previous reading as default
        current_reading.value = newAsset.current_reading;
    } else if (newAsset && !newAsset.current_reading) {
        current_reading.value = '';
    }
});

const status = ref(null)
const remark = ref('')
const spinner = ref(false)

const approveGatePass = async ({ status, remark }) => {
    spinner.value = true;
    const payload = {
        approval_id : JSON.parse(localStorage.getItem('user')).id,
        remark : remark,
        status_id :status
    }

    
    try {
        await axiosInstance.put(`gate-passes/${selectedGatePass.value.id}`,payload);
        showMessage('Done!');
        getGatePasses();
        document.getElementById('close-preview-modal').click()
    } catch (error) {
        showError(error.message);
    } 
    finally {
        spinner.value = false;
    }
};
    onMounted(() => {
        getGatePasses();
    });
</script>