<template>
  <div>

    <div class="btn-group mb-2">
      <button type="button" class="btn btn-success me-2" @click="handleStatus(3)" :disabled="spinner">
        <span v-if="spinner && status === 3" v-html="loadingSpinner()"></span>
        <span v-else>Approve</span>
      </button>

      <button type="button" class="btn btn-danger me-2" @click="handleStatus(4)" :disabled="spinner">
        <span v-if="spinner && status === 4" v-html="loadingSpinner()"></span>
        <span v-else>Reject</span>
      </button>

      <button type="button" class="btn btn-info me-2" @click="handleStatus(14)" :disabled="spinner">
        <span v-if="spinner && status === 14" v-html="loadingSpinner()"></span>
        <span v-else>Remark</span>
      </button>

      <button type="button" class="btn btn-warning" @click="handleStatus(17)" :disabled="spinner">
        <span v-if="spinner && status === 17" v-html="loadingSpinner()"></span>
        <span v-else>On Hold</span>
      </button>
    </div>

    <div v-if="status && block" class="mb-2 text-center">
      <span class="badge rounded-pill"
        :class="{
          'bg-danger': status == 4,
          'bg-success': status == 3,
          'bg-info': status == 14,
          'bg-warning': status == 17
        }"
        style="font-size: 1rem;"
      >
        {{
          status == 3
            ? 'Approve Request'
            : status == 4
              ? 'Reject Request'
              : status == 17
                ? 'Hold Request'
                : 'Fill Remark'
        }}
      </span>
    </div>

    <div class="input-group" v-if="status && block">
      <input
        type="text"
        class="form-control"
        :placeholder="status == 3 ? 'Enter Approval Remark' : status == 4 ? 'Enter Rejection Remark' : 'Enter Remark'"
        v-model="remark"
        :disabled="spinner"
      >

      <button
        type="button"
        class="btn btn-primary me-2"
        :disabled="spinner"
        @click="submit"
      >
        <span v-if="spinner" v-html="loadingSpinner()"></span>
        <span v-else>Save</span>
      </button>
    </div>

  </div>
</template>

<script setup>
import { ref, watch } from 'vue'

/* ✅ PROPS */
const props = defineProps({
  spinner: Boolean,
  loadingSpinner: Function,
  modelValue: Number,
  remarkValue: String
})

/* ✅ EMITS */
const emit = defineEmits([
  'update:modelValue',
  'update:remarkValue',
  'submit'
])

/* ✅ STATE (block stays purely internal — no one outside needs it) */
const block = ref(false)
const status = ref(props.modelValue || null)
const remark = ref(props.remarkValue || '')

/* ✅ WATCHERS — keep local state in sync if parent resets props */
watch(() => props.modelValue, val => status.value = val)
watch(() => props.remarkValue, val => remark.value = val)

watch(status, val => emit('update:modelValue', val))
watch(remark, val => emit('update:remarkValue', val))

/* ✅ ACTION */
const handleStatus = (newStatus) => {
  if (props.spinner) return // Prevent clicking while parent is submitting

  if (status.value === newStatus && block.value) {
    block.value = false
  } else {
    status.value = newStatus
    block.value = true
  }
}

/* ✅ SUBMIT — just hands back what was picked, nothing else */
const submit = () => {
  emit('submit', {
    status: status.value,
    remark: remark.value
  })
  block.value = false
  status.value = null
  remark.value = ''
}
</script>